import java.util.Scanner;
public class JFailCourse3 {
	public static void main(String[] args) {
		//Khatwa 1: Iqra madakhlat al-mudarris
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil darajat al-talib:");
		int studentScore = scan.nextInt();
		System.out.println("Adkhil mutawassit al-saff:");
		int classAverage = scan.nextInt();
		scan.close();
		//Khatwa 2: Iktub al-ta'bir al-mantiqi (boolean) li-tahdid idha kan al-talib yarsib fi al-muqarr
		boolean isFailing = !( studentScore > classAverage );
		System.out.println(isFailing);
	}
}
